package com.contextgraph.service; import com.contextgraph.dto.SearchDtos; import com.contextgraph.model.Document; import com.contextgraph.repository.*; import org.springframework.stereotype.Service; import java.time.*; import java.time.temporal.TemporalAdjusters; import java.util.*; import java.util.stream.*; @Service public class ContextSearchService{final DocumentRepository docs;final UserRepository users;public ContextSearchService(DocumentRepository d,UserRepository u){docs=d;users=u;}public List<SearchDtos.SearchResult>search(String email,String q){Long owner=users.findByEmailIgnoreCase(email).orElseThrow().getId();Set<String>terms=Arrays.stream(q.toLowerCase().replaceAll("[^a-z0-9+# ]"," ").split("\s+")).filter(x->x.length()>2).collect(Collectors.toSet());return docs.findByOwnerIdOrderByCreatedAtDesc(owner).stream().map(d->{String c=(d.getOriginalName()+" "+safe(d.getExtractedText())+" "+safe(d.getKeywords())+" "+safe(d.getEntities())+" "+safe(d.getTopic())).toLowerCase();long hits=terms.stream().filter(c::contains).count();double lexical=terms.isEmpty()?0:(double)hits/terms.size();double topic=d.getTopic()!=null&&q.toLowerCase().contains(d.getTopic().toLowerCase())?1:0;double temporal=time(q,d.getCreatedAt());double score=Math.min(.99,.55*lexical+.20*topic+.15*temporal+.10*recent(d.getCreatedAt()));List<String>r=new ArrayList<>();if(lexical>0)r.add("Semantic/term relevance");if(topic>0)r.add("Topic match");if(temporal>.5)r.add("Temporal context match");if(r.isEmpty())r.add("Related information");return new SearchDtos.SearchResult(d.getId(),d.getOriginalName(),d.getContentType(),d.getTopic(),Math.round(score*1000)/10.0,r,d.getCreatedAt());}).filter(x->x.score()>0).sorted(Comparator.comparingDouble(SearchDtos.SearchResult::score).reversed()).limit(20).toList();}double time(String q,LocalDateTime d){LocalDateTime n=LocalDateTime.now();String x=q.toLowerCase();if(x.contains("last month")){LocalDateTime f=n.minusMonths(1).with(TemporalAdjusters.firstDayOfMonth());LocalDateTime l=n.minusMonths(1).with(TemporalAdjusters.lastDayOfMonth()).withHour(23).withMinute(59);return !d.isBefore(f)&&!d.isAfter(l)?1:0;}if(x.contains("this month"))return d.getMonth()==n.getMonth()&&d.getYear()==n.getYear()?1:0;if(x.contains("recent"))return d.isAfter(n.minusDays(30))?1:0;return 0;}double recent(LocalDateTime d){long days=Math.max(0,Duration.between(d,LocalDateTime.now()).toDays());return Math.max(0,1.0-days/365.0);}String safe(String s){return s==null?"":s;}}